package finance.governance;
import finance.company.*;import finance.debt.CompanyCreditService;import finance.stock.*;import java.math.BigInteger;
public final class CompanyValuationService{private CompanyValuationService(){}public record Summary(long day,long bookAssets,long liabilities,long bookEquity,long averageProfit,long earningsValue,long marketCap,long enterpriseValue,long inventoryValue,long operatingAssetValue,String quality,String riskAdjustment){}public static Summary calculate(Company c,long day){if(c==null)return new Summary(day,0,0,0,0,0,0,0,0,0,"MISSING","company missing");long assets=c.getReportBasedAssetValue(),debt=CompanyCreditService.totalDebt(c.getCompanyId()),equity=signed(BigInteger.valueOf(assets).subtract(BigInteger.valueOf(debt))),profit=c.getSmoothedDailyProfit();long earnings=profit>0&&c.getRecentProfits().size()>=3?cap(BigInteger.valueOf(profit).multiply(BigInteger.valueOf(120))):0;Stock s=StockMarketManager.getStockByCompanyId(c.getCompanyId());long market=s==null?0:cap(BigInteger.valueOf(s.getLastPrice()).multiply(BigInteger.valueOf(s.getVotingShares())));long ev=cap(BigInteger.valueOf(market).add(BigInteger.valueOf(debt)).subtract(BigInteger.valueOf(c.getCash())));String quality=c.getRecentProfits().size()>=3?"SUFFICIENT":"INSUFFICIENT_HISTORY";String risk=c.isBankruptcyRisk()?"bankruptcy risk":profit<0?"negative profitability":"normal";return new Summary(day,assets,debt,equity,profit,earnings,market,ev,c.inventoryValue(),Math.max(0,assets-c.getCash()-c.inventoryValue()),quality,risk);}private static long cap(BigInteger n){return n.max(BigInteger.ZERO).min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}private static long signed(BigInteger n){return n.max(BigInteger.valueOf(Long.MIN_VALUE)).min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}}
